makeMtLab(document.getElementById("lab-l35"),{id:"l35",scenarios:[{"label": "Ví dụ: Dữ liệu hợp lệ", "note": "Chuyển kiểu tự động.", "steps": [{"t": "qty='6000'", "html": "<p class=\"mt-calc\">Chuỗi số<\/p>"}, {"t": "Kết quả", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">6000 &lt;class 'int'&gt;<\/span><\/div>", "ask": {"q": "qty sau kiểm tra có kiểu gì?", "o": ["str", "int", "float"], "a": 1}}]}, {"label": "Ví dụ: Hai lỗi cùng lúc", "note": "Pydantic báo mọi lỗi.", "steps": [{"t": "order_id='WO-412', qty=0", "html": "<p class=\"mt-calc\">Gửi tới model<\/p>"}, {"t": "Lỗi", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">string_pattern_mismatch<\/span><span class=\"ln\" data-n=\"2\">greater_than<\/span><\/div>", "ask": {"q": "Có mấy lỗi?", "o": ["1", "2", "3"], "a": 1}}]}, {"label": "Ví dụ: Xuất JSON", "note": "model_dump_json.", "steps": [{"t": "w.model_dump_json()", "html": "<div class=\"code mes-code\"><span class=\"ln\" data-n=\"1\">{\"order_id\":\"WO-0412\",\"product_id\":\"SP-07\",\"qty\":6000,\"due\":\"2026-11-12T22:00:00+07:00\"}<\/span><\/div>"}, {"t": "Múi giờ được giữ", "html": "<p class=\"mt-calc\">+07:00 còn nguyên<\/p>"}]}, {"label": "Lỗi: Kiểm tra bằng if rải rác", "note": "Dễ sót.", "steps": [{"t": "Kiểm tra qty bằng một câu if", "html": "<p class=\"mt-calc\">if qty &lt;= 0: … nhưng quên kiểm tra mã lệnh<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Một model, mọi ràng buộc ở một chỗ<\/p>"}]}, {"label": "Bẫy: Tin dữ liệu đã qua giao diện", "note": "API vẫn phải kiểm tra.", "steps": [{"t": "Giao diện chặn qty âm", "html": "<p class=\"mt-calc\">Script gọi thẳng API với qty −5<\/p>"}, {"t": "Không có model", "html": "<p class=\"mt-calc\">Lệnh âm vào CSDL<\/p>", "say": "<p>Mọi đường vào đi qua cùng một model.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l35"),"l35",[{"kind": "num", "t": "Ràng buộc", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "qty lớn nhất được chấp nhận?", "a": 100000}, {"q": "qty nhỏ nhất được chấp nhận?", "a": 1}, {"q": "Mã lệnh có bao nhiêu chữ số sau WO-?", "a": 4}], "hints": ["gt=0 nghĩa là lớn hơn 0.", "\\d{4} nghĩa là đúng 4 chữ số."], "why": "100 000; 1; 4."}, {"kind": "pick", "t": "Hợp lệ không?", "d": "<p>Theo model WorkOrderIn.<\/p>", "cats": ["Hợp lệ", "Lỗi 422"], "items": [{"q": "order_id 'WO-0412', qty 6000", "a": 0}, {"q": "order_id 'WO-412'", "a": 1}, {"q": "qty 0", "a": 1}, {"q": "qty '6000' (chuỗi)", "a": 0}, {"q": "qty 150000", "a": 1}], "hints": ["Mã phải đúng 4 chữ số.", "Chuỗi số được chuyển kiểu; số ngoài khoảng thì lỗi."], "why": "WO-0412 và chuỗi '6000' hợp lệ; WO-412, 0, 150 000 lỗi."}, {"kind": "order", "t": "POST một lệnh", "d": "<p>Sắp xếp.<\/p>", "items": ["Nhận thân JSON", "Pydantic kiểm tra và chuyển kiểu", "Nếu sai: trả 422 kèm danh sách lỗi", "Nếu đúng: kiểm tra trùng lệnh", "Ghi và trả 201"], "hints": ["Kiểm tra dữ liệu trước nghiệp vụ.", "Trùng lệnh là 409, sau khi dữ liệu hợp lệ."], "why": "Nhận → kiểm tra → 422 nếu sai → kiểm trùng → 201."}]);
mesSim(document.getElementById("sim-l35"),Object.assign({id:"l35"},{kind:"api",title:"Pydantic kiểm tra dữ liệu lệnh",sub:"Model WorkOrderIn: order_id dạng WO-dddd, qty > 0, due phải có múi giờ. Sửa JSON rồi gửi.",store:{machines:{"L1-M1":{machine_id:"L1-M1",name:"Máy rót",state:"RUNNING",since:"2026-11-12T08:12:00+07:00"},"L1-M2":{machine_id:"L1-M2",name:"Máy dán nắp",state:"DOWN",fault_code:12,since:"2026-11-12T09:40:00+07:00"},"L1-M3":{machine_id:"L1-M3",name:"Máy cân",state:"IDLE",since:"2026-11-12T09:49:00+07:00"}},
 orders:{"WO-0412":{order_id:"WO-0412",product_id:"SP-07",qty:6000,status:"RUNNING"}}},routes:[{m:"GET",p:"/machines",d:"danh sách máy",h:({store})=>({status:200,body:Object.values(store.machines).map(m=>({machine_id:m.machine_id,name:m.name}))})},
 {m:"GET",p:"/machines/{id}/state",d:"trạng thái một máy",h:({params,store})=>{const m=store.machines[params.id];return m?{status:200,body:{machine_id:m.machine_id,state:m.state,fault_code:m.fault_code||0,since:m.since}}:{status:404,body:{detail:"Không có máy "+params.id}}}},
 {m:"POST",p:"/work-orders",d:"tạo lệnh",schema:{order_id:{t:"str",re:"^WO-\\d{4}$"},product_id:{t:"str"},qty:{t:"int",gt:0},due:{t:"dt",tz:1}},h:({body,store})=>store.orders[body.order_id]?{status:409,body:{detail:"Lệnh đã tồn tại"}}:(store.orders[body.order_id]=Object.assign({status:"CREATED"},body),{status:201,body:store.orders[body.order_id]})},
 {m:"POST",p:"/work-orders/{id}/start",d:"bắt đầu lệnh",h:({params,store})=>{const o=store.orders[params.id];if(!o)return{status:404,body:{detail:"Không có lệnh"}};if(o.status==="RUNNING")return{status:409,body:{detail:"Lệnh đang chạy"}};o.status="RUNNING";return{status:200,body:o}}}],method:"POST",path:"/work-orders",rows:8,
 body:'{\n  "order_id": "WO-412",\n  "product_id": "SP-07",\n  "qty": 0,\n  "due": "2026-11-12T22:00:00+07:00"\n}',
 tasks:[{t:"Gửi JSON có sẵn. Đọc từng mục trong <code>detail</code>.",ok:"Hai lỗi cùng lúc: string_pattern_mismatch ở order_id, greater_than ở qty. Giao diện chỉ đúng hai ô.",check:(s,c)=>c.has("http",e=>e.status===422&&e.body.detail.length>=2)},
  {t:"Sửa cả hai lỗi và gửi lại cho tới khi được 201.",check:(s,c)=>c.has("http",e=>e.status===201)},
  {t:"Gửi một lệnh mới có <code>due</code> không múi giờ, ví dụ \"2026-11-12T22:00:00\".",ok:"Bị từ chối: thời điểm không múi giờ không biết là giờ của máy nào (Bài 25).",check:(s,c)=>c.has("http",e=>e.status===422&&JSON.stringify(e.body).includes("due"))},
  {t:"Gửi qty là chuỗi chữ \"sáu nghìn\".",ok:"int_parsing: kiểu sai bị chặn trước khi chạm CSDL.",check:(s,c)=>c.has("http",e=>e.status===422&&JSON.stringify(e.body).includes("int_parsing"))}]}));

